import { applyMove } from './apply-move.ts';
import { flipCells, neighbourhood } from './flip-cells.ts';

/** create() plays a move to check its board (as a game proving its layout winnable would). */
export const PROBE = applyMove;

import { nextInt, seedRng } from '@e07/game-kit/rng/sfc32.ts';

import { flipCells, neighbourhood } from './flip-cells.ts';

/** A draw during play that create() also reaches. */
export function sparkCell(moves: number, size: number): number {
  return nextInt(seedRng(moves), size).value;
}
